# Coset certificate for infiniteness of the invariant-subtree group K (selfrep.build).
# v a vertex with |K.v| = m > 1, phi: Stab_K(v) -> K, k -> k|_v (a homomorphism; K is self-similar),
# L = phi(Stab_K(v)), generated by the pool (sections at v of the Schreier generators of Stab_K(v)).
# If K were finite, [K : L] >= m (|L| <= |Stab_K(v)| = |K|/m).  We certify [K : L] <= i < m by exhibiting
# words t_1 = 1, ..., t_i and, for every generator a and every j, an index j' and a product n of pool
# elements with a t_j = t_j' n exactly in K (checked by selfrep.trivial): then t_1 L u ... u t_i L is closed
# under left multiplication by the generators (involutions, or add inverses), hence equals K.
# So K is infinite; H_x (which maps onto K) is infinite and Gamma is irreducible (Burger-Mozes, Prop. 1.2).
# Candidate words are found on the action on level NL (sympy membership, meet-in-the-middle), then verified.
# usage: kcoset.py census.json side dv D NL idx...
import sys, json, itertools
from sympy.combinatorics import Permutation, PermutationGroup
from lo_census import load
from selfrep import build, act_path, trivial, inv
from kkps import red, words
from kstab import schreier

def run(K, dv, D, NL):
    V = list(itertools.product(K['X'], repeat=NL)); ix = {x: i for i, x in enumerate(V)}
    tp = lambda w: tuple(ix[act_path(K, w, x)[0]] for x in V)
    mul = lambda p, q: tuple(p[i] for i in q)
    def pinv(p):
        r = [0] * len(p)
        for i, x in enumerate(p): r[x] = i
        return tuple(r)
    assert all(K['invL'][a] == a for a in range(K['nL'])), 'generators must be involutions'
    gens = [(a,) for a in range(K['nL'])]
    Kn = PermutationGroup([Permutation(list(tp(g))) for g in gens])
    for v in itertools.product(K['X'], repeat=dv):
        m, sch = schreier(K, v)
        secs = {red(K, act_path(K, s, v)[1]) for s in sch}; secs.discard(())
        pool = sorted(secs | {inv(K, s) for s in secs}, key=lambda s: (len(s), s))
        Ln = PermutationGroup([Permutation(list(tp(s))) for s in pool])
        i = Kn.order() // Ln.order()
        if i >= m: continue
        # coset representatives
        T = [()]
        for w in words(K, 6):
            if all(not Ln.contains(Permutation(list(mul(pinv(tp(t)), tp(w))))) for t in T):
                T.append(w)
            if len(T) == i: break
        if len(T) < i: continue
        ball = {tp(()): ()}; fr = [(tp(()), ())]; P = [(s, tp(s)) for s in pool]
        for _ in range(D):
            nf = []
            for p, w in fr:
                for s, q in P:
                    r = mul(p, q)
                    if r not in ball: ball[r] = w + s; nf.append((r, w + s))
            fr = nf
        table = {}; ok = True
        for a in range(K['nL']):
            for j, t in enumerate(T):
                at = (a,) + t; hit = None
                for j2, t2 in enumerate(T):
                    target = mul(pinv(tp(t2)), tp(at))
                    if not Ln.contains(Permutation(list(target))): continue
                    for x, wx in ball.items():
                        y = mul(pinv(x), target)
                        if y in ball:
                            n = red(K, wx + ball[y])
                            if trivial(K, red(K, inv(K, t2) + at + inv(K, n))): hit = (j2, n); break
                    break
                if hit is None:
                    print('miss', v, i, T, a, j, len(ball), len(table), file=sys.stderr, flush=True); ok = False; break
                table[f'{a},{j}'] = hit
            if not ok: break
        if ok:
            return dict(v=v, orbit=m, index_bound=len(T), reps=T, pool=pool, table=table)
    return None

if __name__ == "__main__":
    path, side, dv, D, NL = sys.argv[1], sys.argv[2], *map(int, sys.argv[3:6])
    for i, G in load(path):
        if i in set(map(int, sys.argv[6:])):
            K = build(G, side)
            print(json.dumps(dict(census=path, idx=i, side=side, fixed_letter=K['f'], dv=dv, D=D, NL=NL,
                                  certificate=run(K, dv, D, NL))), flush=True)
